288	    @Test
289	    void currentReviewBecomesStaleAfterZoneChangeAndRouteReplace() {
290	        service.createRoute(
291	                new RouteCreateRequest("st", pts(0, 10, 100, 10), "req-" + rid("route")));
292	        MutationResponse rev = service.review(
293	                new ReviewRequest("st", 1, 0L, "req-" + rid("review")));
294	        ReviewResultDto dto = dataOf(rev);
295	        assertEquals("CLEAR", dto.conclusion());
296	
297	        // 刚完成：当前结论可用
298	        ReviewResultDto current1 = service.getCurrentReview("st");
299	        assertEquals("CLEAR", current1.conclusion());
300	        assertTrue(current1.current());
301	
302	        // 空域变化：当前结论必须 STALE，旧 CLEAR 不能当成当前通过
303	        service.createZone(zoneReq("nz", -90, -90, -80, -80));
304	        ReviewResultDto stale1 = service.getCurrentReview("st");
305	        assertEquals("STALE", stale1.conclusion());
306	        assertFalse(stale1.current());
307	        // 历史结论不变
308	        assertEquals("CLEAR", service.getReview(dto.reviewId()).conclusion());
309	
310	        // 用新空域版本重新审核 → CLEAR，恢复可用
311	        MutationResponse rev2 = service.review(
312	                new ReviewRequest("st", 1, 1L, "req-" + rid("review")));
313	        assertTrue(dataOf(rev2).current());
314	        assertEquals("CLEAR", service.getCurrentReview("st").conclusion());
315	
316	        // 航线替换后再次 STALE
317	        service.replaceRoute(new RouteReplaceRequest(
318	                "st", 1, pts(0, 10, 100, 10), "req-" + rid("replace")));
319	        assertEquals("STALE", service.getCurrentReview("st").conclusion());
320	
321	        // 无审核记录查询 404
322	        ApiException ex = assertThrows(ApiException.class,
323	                () -> service.getCurrentReview("never-reviewed"));
324	        assertEquals(HttpStatus.NOT_FOUND, ex.status());
325	    }
