@Service
public class DiversionPriorityService {

    static final String KIND_PRIORITY_REVIEW = "PRIORITY_REVIEW";
    static final String KIND_DEPARTURE = "DEPARTURE";
    static final String KIND_CAPACITY_SET = "CAPACITY_SET";

