248	    /**
249	     * 容量裁决：按规范化桶序逐桶统计占用与单元容量。
250	     *
251	     * <p>NORMAL：任一桶加入本航线后超容即拒绝，列出该桶占用方。</p>
252	     *
253	     * <p>EMERGENCY：抢占以航线为粒度（置换一条航线会释放它在全部桶上的占用）。
254	     * 按桶序贪心：桶仍超容时，从该桶未起飞 NORMAL 占用中按批件标识升序补选
255	     * 最小数量加入完整受影响集合；可抢占数量不足时，把剩余缺口对应的不可抢占
256	     * 占用（已起飞 NORMAL 或另一 EMERGENCY）列入 blocking，最终返回 422。</p>
257	     */
258	    private void evaluateCapacity(List<SpaceBucket> buckets,
259	                                  DiversionPriority priority,
260	                                  String selfClearanceId,
261	                                  Map<String, ClearancePo> preemptById,
262	                                  List<CapacityConflictException.BlockingRoute> blocking) {
263	        Map<String, CapacityConflictException.BlockingRoute> blockingById = new LinkedHashMap<>();
264	        for (SpaceBucket bucket : buckets) {
265	            Integer configured = capacityRepo.findCapacity(bucket.cellX(), bucket.cellY());
266	            int capacity = configured == null ? DEFAULT_CAPACITY : configured;
267	            List<BucketOccupancyPo> occupants = capacityRepo.findOccupants(
268	                    bucket.cellX(), bucket.cellY(), bucket.timeBucket());
269	            Map<String, ClearancePo> perOccupantClearances = loadOccupantClearances(occupants);
270	
271	            if (priority == DiversionPriority.NORMAL) {
272	                if (occupants.size() + 1 > capacity) {
273	                    for (BucketOccupancyPo occ : occupants) {
274	                        blockingById.putIfAbsent(occ.clearanceId(),
275	                                toBlocking(occ, perOccupantClearances, false));
276	                    }
277	                }
278	                continue;
279	            }
280	
281	            // EMERGENCY：剔除本航线旧批件（将在第 7 步作旧）与已选受影响航线后重算
282	            List<BucketOccupancyPo> effective = occupants.stream()
283	                    .filter(o -> !o.clearanceId().equals(selfClearanceId))
284	                    .filter(o -> !preemptById.containsKey(o.clearanceId()))
285	                    .toList();
286	            int deficit = effective.size() + 1 - capacity;
287	            if (deficit <= 0) {
288	                continue;
289	            }
290	            List<BucketOccupancyPo> removable = effective.stream()
291	                    .filter(o -> {
292	                        ClearancePo c = perOccupantClearances.get(o.clearanceId());
293	                        return c != null
294	                                && DiversionPriority.NORMAL.name().equals(c.priority())
295	                                && ClearanceStatus.APPROVED.name().equals(c.status());
296	                    })
297	                    .sorted(java.util.Comparator.comparing(BucketOccupancyPo::clearanceId))
298	                    .toList();
299	            int take = Math.min(deficit, removable.size());
300	            for (int i = 0; i < take; i++) {
301	                BucketOccupancyPo chosen = removable.get(i);
302	                preemptById.putIfAbsent(chosen.clearanceId(),
303	                        perOccupantClearances.get(chosen.clearanceId()));
304	            }
305	            if (deficit > removable.size()) {
306	                // 可抢占集合用尽后仍有缺口：不可抢占占用导致 422
307	                List<BucketOccupancyPo> nonRemovable = effective.stream()
308	                        .filter(o -> !removable.contains(o))
309	                        .sorted(java.util.Comparator.comparing(BucketOccupancyPo::clearanceId))
310	                        .toList();
311	                int blockersNeeded = deficit - removable.size();
312	                for (int i = 0; i < blockersNeeded && i < nonRemovable.size(); i++) {
313	                    BucketOccupancyPo occ = nonRemovable.get(i);
314	                    blockingById.putIfAbsent(occ.clearanceId(),
315	                            toBlocking(occ, perOccupantClearances, true));
316	                }
317	            }
318	        }
319	        if (!blockingById.isEmpty()) {
320	            // 不足时本次抢占不生效：受影响集合仅用于错误说明，不做任何更新
321	            preemptById.clear();
322	            blocking.addAll(blockingById.values());
323	        }
324	    }
