363	    public MutationResponse registerDeparture(DepartureRequest request) {
364	        return withIdempotency(request.requestId(), KIND_DEPARTURE, canonicalHash(request), () -> {
365	            // 与审查/抢占/区域更新串行裁决
366	            airspaceRepo.getGlobalVersionForUpdate();
367	            ClearancePo found = capacityRepo.findClearance(request.clearanceId());
368	            if (found == null) {
369	                throw new ApiException(HttpStatus.NOT_FOUND, "CLEARANCE_NOT_FOUND",
370	                        "批件不存在: " + request.clearanceId());
371	            }
372	            // 对批件行做真实更新加行级写锁，随后重读，保证状态判定基于持锁后的最新已提交值
373	            lockClearanceRow(found.clearanceId());
374	            ClearancePo clearance = capacityRepo.findClearance(request.clearanceId());
375	            if (ClearanceStatus.DEPARTED.name().equals(clearance.status())) {
376	                if (clearance.requestId().equals(request.requestId())) {
377	                    throw new ApiException(HttpStatus.CONFLICT, "RESOURCE_CONFLICT",
378	                            "并发资源冲突，请稍后使用相同 requestId 与参数重试");
379	                }
380	                throw new ApiException(HttpStatus.CONFLICT, "CLEARANCE_ALREADY_DEPARTED",
381	                        "批件已起飞登记: " + request.clearanceId());
382	            }
383	            if (!ClearanceStatus.APPROVED.name().equals(clearance.status())) {
384	                throw new ApiException(HttpStatus.CONFLICT, "CLEARANCE_NOT_ACTIVE",
385	                        "批件状态为 " + clearance.status() + "，不能登记起飞");
386	            }
387	            long globalVersion = airspaceRepo.getGlobalVersion();
388	            RoutePo route = routeRepo.findRoute(clearance.routeId());
389	            if (route == null || route.version() != clearance.routeVersion()
390	                    || globalVersion != clearance.airspaceVersion()) {
391	                // 版本失效：按既有规则拒绝起飞，需重新提交审查（旧批件随后作旧）
392	                throw new ApiException(HttpStatus.CONFLICT, "VERSION_CONFLICT",
393	                        "批件依据的航线/空域版本已失效，请重新提交审查");
394	            }
395	            long now = nowMillis();
396	            int changed = capacityRepo.markDeparted(clearance.clearanceId(), now);
397	            if (changed != 1) {
398	                throw new ApiException(HttpStatus.CONFLICT, "CLEARANCE_STATE_CONFLICT",
399	                        "批件状态已变化，请重试");
400	            }
401	            return new DepartureResultDto(clearance.clearanceId(), clearance.routeId(),
402	                    ClearanceStatus.DEPARTED.name(), now);
403	        });
404	    }
