509	    private static List<SpaceBucket> normalizeBuckets(List<SpaceTimePointDto> segments) {
510	        long previous = Long.MIN_VALUE;
511	        TreeSet<SpaceBucket> distinct = new TreeSet<>();
512	        for (SpaceTimePointDto dto : segments) {
513	            if (dto.atMillis() <= previous) {
