561	    private MutationResponse resolveAfterRace(String requestId, String kind, String paramHash,
562	                                              ApiException original) {
563	        DedupPo winner = txTemplate.execute(status -> reviewRepo.findDedup(requestId));
564	        if (winner == null) {
565	            throw original;
566	        }
567	        ensureSameRequest(winner, kind, paramHash);
568	        return deserializeReplay(winner);
