613	    /**
614	     * 计算请求参数的规范化哈希（SHA-256），指纹含优先级、事件号、
615	     * 航线版本、空域版本与时空段采样点；字段按键名字典序递归排序，列表保持顺序。
616	     */
617	    private String canonicalHash(Object request) {
618	        try {
619	            JsonNode sorted = canonicalize(objectMapper.valueToTree(request));
620	            String canonical = objectMapper.writeValueAsString(sorted);
621	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
622	            return HexFormat.of().formatHex(digest.digest(canonical.getBytes(StandardCharsets.UTF_8)));
623	        } catch (JsonProcessingException | NoSuchAlgorithmException ex) {
624	            throw new IllegalStateException("无法计算请求哈希", ex);
625	        }
626	    }
627	
628	    private static JsonNode canonicalize(JsonNode node) {
629	        if (node.isObject()) {
630	            ObjectNode sorted = JsonNodeFactory.instance.objectNode();
631	            List<String> names = new ArrayList<>();
632	            node.fieldNames().forEachRemaining(names::add);
633	            names.sort(String::compareTo);
634	            for (String name : names) {
635	                sorted.set(name, canonicalize(node.get(name)));
636	            }
637	            return sorted;
638	        }
639	        if (node.isArray()) {
640	            ArrayNode array = JsonNodeFactory.instance.arrayNode();
641	            node.forEach(child -> array.add(canonicalize(child)));
642	            return array;
643	        }
644	        return node;
645	    }
